/**
 * A collection of constants used throughout the integration module.
 * Using a frozen object to prevent accidental modification.
 */
const Constants = Object.freeze({
    // The base URL for the fictional CryptexBit API.
    // In a real production environment, this should come from a configuration file or environment variable.
    API_BASE_URL: 'https://api.cryptexbit.com/v1',

    // API endpoint for processing payments.
    PAYMENT_ENDPOINT: '/payments/charge',

    // Supported contactless payment methods.
    PaymentMethod: {
        APPLE_PAY: 'APPLE_PAY',
        GOOGLE_PAY: 'GOOGLE_PAY',
    },

    // Supported currencies (ISO 4217 codes). This list can be expanded as needed.
    SUPPORTED_CURRENCIES: ['USD', 'EUR', 'GBP', 'JPY'],

    // Standard HTTP headers.
    HEADERS: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
    },
});

/**
 * Custom error class for handling API-specific errors from CryptexBit.
 * This allows for more specific error handling in the calling code.
 */
class CryptexBitApiError extends Error {
    /**
     * @param {string} message - The error message.
     * @param {number} [statusCode] - The HTTP status code from the API response.
     * @param {string} [errorCode] - A specific error code from the API response body.
     * @param {string} [requestId] - The request ID from the API for tracing.
     */
    constructor(message, statusCode, errorCode, requestId) {
        super(message);
        this.name = 'CryptexBitApiError';
        this.statusCode = statusCode;
        this.errorCode = errorCode;
        this.requestId = requestId;
    }
}

/**
 * Processes a contactless payment through the CryptexBit API.
 *
 * This function constructs and sends a payment request to the CryptexBit backend,
 * handling authentication, data validation, and error management. It is designed
 * to be used with payment tokens generated by third-party wallet services like
 * Apple Pay or Google Pay.
 *
 * @async
 * @function processContactlessPayment
 * @param {object} params - The parameters for the payment processing.
 * @param {string} params.paymentToken - The encrypted payment token received from the third-party wallet (e.g., Apple Pay, Google Pay).
 * @param {string} params.paymentMethod - The payment method used. Must be one of the values from `Constants.PaymentMethod`.
 * @param {object} params.orderDetails - An object containing details about the order.
 * @param {number} params.orderDetails.amount - The transaction amount in the smallest currency unit (e.g., cents for USD). Must be a positive integer.
 * @param {string} params.orderDetails.currency - The three-letter ISO currency code (e.g., 'USD').
 * @param {string} params.orderDetails.orderId - A unique identifier for the order from the merchant's system.
 * @param {string} params.apiKey - The merchant's secret API key for authenticating with CryptexBit.
 * @returns {Promise<object>} A promise that resolves with the successful transaction data from the CryptexBit API.
 * @throws {TypeError} If any of the required parameters are missing or invalid.
 * @throws {CryptexBitApiError} If the API returns an error (e.g., payment declined, invalid API key).
 * @throws {Error} If a network or other unexpected error occurs during the request.
 */
async function processContactlessPayment({
    paymentToken,
    paymentMethod,
    orderDetails,
    apiKey
}) {
    // --- 1. Input Validation ---
    if (!paymentToken || typeof paymentToken !== 'string') {
        throw new TypeError('Invalid or missing "paymentToken". It must be a non-empty string.');
    }
    if (!apiKey || typeof apiKey !== 'string') {
        throw new TypeError('Invalid or missing "apiKey". It must be a non-empty string.');
    }
    if (!paymentMethod || !Object.values(Constants.PaymentMethod).includes(paymentMethod)) {
        throw new TypeError(`Invalid "paymentMethod". Must be one of: ${Object.values(Constants.PaymentMethod).join(', ')}`);
    }
    if (!orderDetails || typeof orderDetails !== 'object') {
        throw new TypeError('Invalid or missing "orderDetails" object.');
    }

    const { amount, currency, orderId } = orderDetails;
    if (!Number.isInteger(amount) || amount <= 0) {
        throw new TypeError('Order "amount" must be a positive integer (smallest currency unit).');
    }
    if (!currency || !Constants.SUPPORTED_CURRENCIES.includes(currency.toUpperCase())) {
        throw new TypeError(`Unsupported "currency". Must be one of: ${Constants.SUPPORTED_CURRENCIES.join(', ')}`);
    }
    if (!orderId || typeof orderId !== 'string') {
        throw new TypeError('Order "orderId" must be a non-empty string.');
    }

    // --- 2. API Request Preparation ---
    const apiUrl = `${Constants.API_BASE_URL}${Constants.PAYMENT_ENDPOINT}`;

    const requestBody = {
        source: {
            type: 'token',
            method: paymentMethod,
            token: paymentToken,
        },
        amount,
        currency: currency.toUpperCase(),
        merchant_order_id: orderId,
        capture: true, // Automatically capture the funds upon successful authorization.
    };

    const requestOptions = {
        method: 'POST',
        headers: {
            ...Constants.HEADERS,
            'Authorization': `Bearer ${apiKey}`,
            // Idempotency key prevents accidental duplicate charges.
            'Idempotency-Key': `idem-${orderId}`,
        },
        body: JSON.stringify(requestBody),
    };

    // --- 3. API Call and Response Handling ---
    try {
        const response = await fetch(apiUrl, requestOptions);

        // The 'x-request-id' header is useful for debugging with the API provider.
        const requestId = response.headers.get('x-request-id');

        if (!response.ok) {
            // Attempt to parse the error body for more details.
            let errorData = { message: `API request failed with status ${response.status}` };
            try {
                errorData = await response.json();
            } catch (e) {
                // The response body was not valid JSON, use the generic message.
            }

            throw new CryptexBitApiError(
                errorData.error?.message || errorData.message,
                response.status,
                errorData.error?.code,
                requestId
            );
        }

        // If the request was successful, parse and return the JSON body.
        const responseData = await response.json();
        return responseData.data; // Assuming the API wraps the result in a 'data' object.

    } catch (error) {
        // Re-throw API errors to be handled by the caller.
        if (error instanceof CryptexBitApiError) {
            throw error;
        }
        // Handle network errors or other unexpected issues.
        throw new Error(`Network error or unexpected issue during payment processing: ${error.message}`);
    }
}


